css:
/* the same geometry fixes as the other CARD formats (wkhtmltopdf, RTL) */
.print-format { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }
.print-format-gutter { padding: 0 !important; }
.cpf { text-rendering: auto; font-family: 'Noto Sans Arabic', 'Noto Sans', 'Segoe UI', Tahoma, sans-serif; color: #000; font-size: 11px; line-height: 1.6; }
.cpf table { width: 100%; border-collapse: collapse; }
.cpf .h { text-align: center; border-bottom: 1.5px solid #000; padding-bottom: 2mm; margin-bottom: 3mm; }
.cpf .h .co { font-size: 14px; font-weight: bold; }
.cpf .h .t { font-size: 13px; font-weight: bold; margin-top: 1mm; }
.cpf .h .mv { font-size: 12px; margin-top: 0.5mm; }
.cpf .h .m { width: 60%; margin: 0.5mm auto 0; }
.cpf .h .m td { border: none; text-align: center; font-size: 10px; padding: 0 2mm; white-space: nowrap; }
.cpf .meta th, .cpf .meta td { border: 1px solid #000; padding: 1.5mm 2.5mm; vertical-align: middle; word-wrap: break-word; }
/* old Qt WebKit (wkhtmltopdf) follows CSS direction, not the dir attribute, and has no text-align: start */
.cpf.rtl { direction: rtl; }
.cpf.rtl .meta th, .cpf.rtl .meta td, .cpf.rtl .stmt { text-align: right; }
.cpf.ltr { direction: ltr; }
.cpf.ltr .meta th, .cpf.ltr .meta td, .cpf.ltr .stmt { text-align: left; }
.cpf .meta th { width: 16%; font-weight: bold; white-space: nowrap; }
.cpf .stmt { margin-top: 4mm; font-size: 10.5px; }
.cpf .sign { margin-top: 14mm; }
.cpf .sign td { width: 50%; text-align: center; border: none; padding: 0 8mm; font-weight: bold; }
.cpf .sign .l { border-bottom: 1px solid #000; height: 12mm; margin-bottom: 1.5mm; }
.cpf .sign .n { font-weight: normal; margin-top: 1mm; }

html:
{%- set L = doc.meta.get_label -%}
{%- set company_name = (frappe.db.get_value("Company", doc.company, "company_name") or doc.company) if doc.company else "" -%}
{%- set rtl = frappe.lang in ("ar", "he", "fa", "ps", "ur") -%}
{%- set worker = doc.employee_name or doc.employee -%}
{%- set mate = (frappe.db.get_value("Employee", doc.to_employee, "employee_name") or doc.to_employee) if doc.to_employee else "" -%}
{%- set issuer_user = doc.handed_by or frappe.session.user -%}
{%- set issuer = frappe.db.get_value("User", issuer_user, "full_name") or issuer_user -%}
{#- who gives and who takes the tool in this movement -#}
{%- if doc.movement == "Return" -%}
  {%- set giver, taker = worker, issuer -%}
{%- elif doc.movement == "Transfer" -%}
  {%- set giver, taker = worker, mate -%}
{%- else -%}
  {%- set giver, taker = issuer, worker -%}
{%- endif -%}
{%- set project_disp = (frappe.db.get_value("Project", doc.project, "project_name") or doc.project) if doc.project else "" -%}
{%- set machine_disp = (frappe.db.get_value("Card Equipment", doc.card_equipment, "equipment_name") or doc.card_equipment) if doc.card_equipment else "" -%}
<div class="cpf {{ 'rtl' if rtl else 'ltr' }}" dir="{{ 'rtl' if rtl else 'ltr' }}">
  <div class="h">
    <div class="co">{{ company_name|e }}</div>
    <div class="t">{{ _("Tool Handover Receipt") }}</div>
    <div class="mv">{{ _(doc.movement) }}{% if doc.docstatus == 2 %} ({{ _("Cancelled") }}){% endif %}</div>
    <table class="m"><tr>
      <td><span dir="ltr">{{ doc.name }}</span></td>
      <td>{{ _(L("date")) }}: <span dir="ltr">{{ frappe.utils.formatdate(doc.date) if doc.date else "" }}</span></td>
    </tr></table>
  </div>
  <table class="meta">
    <tr>
      <th>{{ _(L("employee")) }}</th><td>{{ worker|e }} <span dir="ltr">({{ doc.employee }})</span></td>
      {%- if doc.to_employee %}
      <th>{{ _(L("to_employee")) }}</th><td>{{ mate|e }} <span dir="ltr">({{ doc.to_employee }})</span></td>
      {%- else %}
      <th>{{ _(L("warehouse")) }}</th><td>{{ (doc.warehouse or "")|e }}</td>
      {%- endif %}
    </tr>
    <tr>
      <th>{{ _(L("item_code")) }}</th><td>{{ (doc.item_name or doc.item_code)|e }} <span dir="ltr">({{ doc.item_code }})</span></td>
      <th>{{ _(L("qty")) }}</th><td><span dir="ltr">{{ doc.get_formatted("qty") }}</span>{% if doc.serial_no %} — <span dir="ltr">{{ doc.serial_no|e }}</span>{% endif %}</td>
    </tr>
    <tr>
      <th>{{ _(L("card_equipment")) }}</th><td>{{ machine_disp|e }}</td>
      <th>{{ _(L("project")) }}</th><td>{{ project_disp|e }}</td>
    </tr>
    {%- if doc.notes %}
    <tr><th>{{ _(L("notes")) }}</th><td colspan="3">{{ doc.notes|e }}</td></tr>
    {%- endif %}
  </table>
  <div class="stmt">{{ _("The receiver confirms receiving the tool above in good condition and is responsible for it until it is returned or handed over.") }}</div>
  <table class="sign"><tr>
    <td><div class="l"></div>{{ _("Handed over by") }}<div class="n">{{ giver|e }}</div></td>
    <td><div class="l"></div>{{ _("Received by") }}<div class="n">{{ taker|e }}</div></td>
  </tr></table>
</div>
